<?php
/** Admin-only manual commands: changes two selected text fields on the website after opt-in. */
$pageTitle='ویرایش محدود خدمات و تیم سایت'; require_login(); header('Cache-Control: no-store');
require_once __DIR__.'/../includes/site_content_commands.php';
require_once __DIR__.'/../includes/site_content_lookup.php';
$me=(int)($_SESSION['user_id'] ?? 0);
try { $st=$pdo->prepare('SELECT status,role FROM users WHERE id=?'); $st->execute([$me]); $actor=$st->fetch(PDO::FETCH_ASSOC);
    if (!is_strict_admin() || !$actor || $actor['status']!=='active' || $actor['role']!=='admin') { http_response_code(403); echo 'دسترسی مجاز نیست.'; return; }
} catch (Throwable $e) { http_response_code(503); echo 'بررسی دسترسی ممکن نیست.'; return; }
$readonly=is_nazer_kol() || (!access_is_special_account() && access_mode('crm_customers')==='viewer');
$configured=content_command_configured(true); $ready=false;
if ($configured) $ready=crm_content_command_ensure($pdo);
else { try { $pdo->query('SELECT 1 FROM crm_site_content_commands LIMIT 1'); $ready=true; } catch (Throwable $e) {} }
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES | ENT_SUBSTITUTE,'UTF-8');
$preview=null; $baseline=null; $lookup=null; $listing=null; $notice='';
if (($_SERVER['REQUEST_METHOD'] ?? '')==='POST') {
    try {
        $action=$_POST['action'] ?? null; $kind=$_POST['kind'] ?? null; $rawId=$_POST['object_id'] ?? null; $token=$_POST['token'] ?? null;
        if ($readonly || !is_string($action) || !in_array($action,['list','lookup','preview','enqueue'],true) || !is_string($kind) || !in_array($kind,['service','service_en','team'],true)) throw new DomainException('درخواست یا پیکربندی معتبر نیست.');
        if ($action==='list') {
            $after=$_POST['after_id'] ?? null;
            if (!content_lookup_configured(true) || !content_lookup_list_enabled($kind) || !is_string($after) || !preg_match('/^(0|[1-9][0-9]{0,17})$/D',$after)) throw new DomainException('صفحهٔ فهرست معتبر نیست.');
            $listing=crm_content_lookup_list_fetch($kind,(int)$after);
        } elseif (!is_string($rawId) || !preg_match('/^[1-9][0-9]{0,17}$/D',$rawId)) throw new DomainException('شناسه معتبر نیست.');
        if ($action==='lookup') {
            $lookup=crm_content_lookup_fetch($kind,(int)$rawId);
            if (!$lookup['found']) { $lookup=null; throw new DomainException('رکورد در سایت یافت نشد؛ هویت و منبع را دوباره بررسی کنید.'); }
        } elseif ($action!=='list') {
            if (!$ready || !$configured || !content_command_kind_enabled($kind) || !is_string($token)) throw new DomainException('درخواست یا پیکربندی معتبر نیست.');
            $first=$_POST['first'] ?? null; $second=$_POST['second'] ?? null; if (!is_string($first) || !is_string($second)) throw new DomainException('متن معتبر نیست.');
            $fields=$kind==='service'?['title_fa'=>$first,'description_fa'=>$second]:($kind==='service_en'?['title_en'=>$first,'description_en'=>$second]:['name'=>$first,'role'=>$second]);
            $now=time(); $probe=['type'=>content_command_type($kind),'command_id'=>str_repeat('a',32),'source_id'=>SITE_CONTENT_COMMAND_SOURCE_ID,'object_id'=>(int)$rawId,'actor_id'=>$me,'expected_token'=>$token,'issued_at'=>$now,'expires_at'=>$now+900,'fields'=>$fields];
            if (!content_command_validate($probe,SITE_CONTENT_COMMAND_SOURCE_ID)) throw new DomainException('متن، شناسه یا نسخه معتبر نیست؛ فاصلهٔ ابتدا/انتها مجاز نیست.');
            if ($action==='preview') {
                if (($_POST['compare'] ?? null)==='1') {
                    if (!content_lookup_matches_command() || !content_lookup_kind_enabled($kind)) throw new DomainException('دریافت و فرمان به منبع یکسان متصل نیستند یا غیرفعال‌اند.');
                    $baseline=crm_content_lookup_fetch($kind,(int)$rawId);
                    if (!$baseline['found'] || !hash_equals($baseline['token'],$token)) { $baseline=null; throw new DomainException('رکورد سایت تغییر کرده یا موجود نیست؛ دوباره دریافت و بررسی کنید.'); }
                }
                $preview=['kind'=>$kind,'object_id'=>$rawId,'token'=>$token,'first'=>$first,'second'=>$second];
            } else {
                crm_content_command_enqueue($pdo,$me,true,$kind,(int)$rawId,$token,$fields,$now,($_POST['confirm_identity'] ?? null)==='1' && ($_POST['confirm_change'] ?? null)==='1');
                showToast('فرمان در صف ثبت شد؛ هنوز تضمینی برای تغییر سایت نیست.'); redirect('index.php?page=site_content_commands');
            }
        }
    } catch (Throwable $e) { error_log('Content command request failed: '.get_class($e)); $notice=$e instanceof DomainException?$e->getMessage():'ثبت فرمان ممکن نیست.'; }
}
$rows=[]; if ($ready) { try { $st=$pdo->query('SELECT command_id,kind,object_id,actor_id,state,created_at,completed_at,payload FROM crm_site_content_commands ORDER BY created_at DESC,command_id DESC LIMIT 30'); $rows=$st->fetchAll(PDO::FETCH_ASSOC); } catch (Throwable $e) { $ready=false; } }
include 'includes/header.php';
?>
<div class="page-header"><h1>ویرایش محدود خدمات و تیم سایت</h1><p>این قابلیت آزمایشی است: فقط عنوان و توضیح فارسی یا انگلیسی یک خدمت یا نام و نقش یک عضو موجود را تغییر می‌دهد؛ ایجاد، حذف، انتشار، تصویر و اطلاعات تماس را تغییر نمی‌دهد. دو سامانه مستقل می‌مانند.</p></div>
<div class="card" style="padding:16px"><p><strong>برای شناسایی صحیح، رکورد سایت را مستقل بررسی کنید. دریافت اختیاری فقط دو فیلد را در همان لحظه نشان می‌دهد و هنگام پیش‌نمایش دوباره بررسی می‌شود؛ در روش دستی باید نسخه را از پنل سایت کپی کنید. سایت هنگام اجرای فرمان نسخه را دوباره می‌سنجد. تغییر و بازگشت، استفادهٔ مجدد شناسه یا تغییر بعدی ممکن است شناسایی نشوند؛ داده و نسخه اثبات هویت نیستند.</strong></p>
<p>برای انگلیسی خدمت، مقدار NULL هنگام دریافت خالی نمایش داده می‌شود و ذخیرهٔ متن خالی به رشتهٔ خالی تبدیلش می‌کند، نه NULL. متن فرمان‌ها در CRM و بکاپ آن باقی می‌ماند؛ نام اعضای تیم می‌تواند اطلاعات شخصی باشد. هر فرمان ۱۵ دقیقه اعتبار دارد؛ دریافت گمشده نتیجه را نامعلوم می‌کند. applied فقط نتیجهٔ لحظهٔ اجراست، نه وضعیت فعلی. پنل قدیمی تا تطبیق و آزمون کامل حفظ شود.</p>
<?php if (!$configured): ?><p>ارسال غیرفعال یا پیکربندی نشده است.</p><?php endif; ?><?php if (!$ready): ?><p>جدول فرمان آماده نیست.</p><?php endif; ?><?php if ($notice): ?><p role="alert"><?= $h($notice) ?></p><?php endif; ?>
<?php if ($preview): ?><h3><?= $baseline?'مقایسه دو فیلد دریافت‌شده از سایت با متن جدید':'پیش‌نمایش متن جدید (بدون مقایسه با سایت)' ?></h3><?php if ($baseline): ?><p>مقادیر سایت در زمان پیش‌نمایش دریافت شده‌اند؛ ممکن است بعداً تغییر کنند.</p><h4>دو فیلد فعلی سایت</h4><p><strong><?= $h($baseline['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($baseline['second']) ?></pre><h4>مقادیر پیشنهادی جدید</h4><?php endif; ?><p>نوع: <?= $preview['kind']==='service'?'خدمت فارسی':($preview['kind']==='service_en'?'خدمت انگلیسی':'عضو تیم') ?> — شناسه سایت <?= $h($preview['object_id']) ?></p><p><strong><?= $h($preview['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($preview['second']) ?></pre>
<form method="post" onsubmit="return confirm('این فرمان ممکن است متن عمومی سایت را تغییر دهد. ارسال شود؟');"><?= get_csrf_field() ?><input type="hidden" name="action" value="enqueue"><?php foreach ($preview as $k=>$v): ?><input type="hidden" name="<?= $h($k) ?>" value="<?= $h($v) ?>"><?php endforeach; ?>
<label><input type="checkbox" name="confirm_identity" value="1" required> شناسه، نسخه و هویت رکورد فعلی را مستقل بررسی کردم.</label><br><label><input type="checkbox" name="confirm_change" value="1" required> متن جدید را بررسی کردم و می‌دانم ارسال ممکن است سایت را تغییر دهد.</label><br><button class="btn" type="submit">ثبت فرمان برای ارسال</button></form><?php endif; ?>
<?php if (!$readonly && content_lookup_configured(true)): foreach (['service'=>'خدمات','team'=>'اعضای تیم'] as $listKind=>$listLabel): if (!content_lookup_list_enabled($listKind)) continue; ?>
<form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="list"><input type="hidden" name="kind" value="<?= $h($listKind) ?>"><input type="hidden" name="after_id" value="0"><button class="btn">دریافت فهرست <?= $h($listLabel) ?> از سایت</button></form><?php endforeach; endif; ?>
<?php if ($listing): ?><h3>فهرست لحظه‌ای <?= $listing['kind']==='service'?'خدمات':'اعضای تیم' ?> از سایت</h3><p>فقط شناسه، نام/عنوان و برچسب فعال نمایش داده می‌شوند. صفحه‌بندی مستقل و لحظه‌ای است؛ وضعیت، هویت، کامل‌بودن یا درستی منبع تضمین نمی‌شود. اعضای غیرفعال هم ممکن است نمایش داده شوند.</p><table class="data-table"><thead><tr><th>شناسه سایت</th><th>نام/عنوان</th><th>برچسب</th><th>مشاهده</th></tr></thead><tbody>
<?php foreach ($listing['items'] as $item): ?><tr><td><?= (int)$item['id'] ?></td><td><?= $h($item['label']) ?></td><td><?= $item['is_active']===1?'فعال':'غیرفعال' ?></td><td><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="lookup"><input type="hidden" name="kind" value="<?= $h($listing['kind']) ?>"><input type="hidden" name="object_id" value="<?= (int)$item['id'] ?>"><button class="btn">دریافت دو فیلد</button></form><?php if ($listing['kind']==='service' && content_lookup_kind_enabled('service_en')): ?><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="lookup"><input type="hidden" name="kind" value="service_en"><input type="hidden" name="object_id" value="<?= (int)$item['id'] ?>"><button class="btn">دریافت انگلیسی</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$listing['items']): ?><tr><td colspan="4">در این صفحه رکوردی مشاهده نشد؛ این اثبات خالی‌بودن سایت نیست.</td></tr><?php endif; ?></tbody></table>
<?php if ($listing['next_after']!==null): ?><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="list"><input type="hidden" name="kind" value="<?= $h($listing['kind']) ?>"><input type="hidden" name="after_id" value="<?= (int)$listing['next_after'] ?>"><button class="btn">صفحه بعد</button></form><?php endif; ?><?php endif; ?>
<?php if (!$readonly && content_lookup_configured(true)): foreach (['service'=>'خدمت فارسی','service_en'=>'خدمت انگلیسی','team'=>'عضو تیم'] as $lookupKind=>$lookupLabel): if (!content_lookup_kind_enabled($lookupKind)) continue; ?>
<h3>دریافت فقط دو فیلد <?= $h($lookupLabel) ?> از سایت</h3><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="lookup"><input type="hidden" name="kind" value="<?= $h($lookupKind) ?>"><label>شناسه سایت <input name="object_id" inputmode="numeric" required></label> <button class="btn">دریافت از سایت</button></form><?php endforeach; endif; ?>
<?php if ($lookup): ?><h3>دادهٔ دریافت‌شده از سایت</h3><p>شناسه <?= (int)$lookup['object_id'] ?> — نوع <?= $lookup['kind']==='service'?'خدمت فارسی':($lookup['kind']==='service_en'?'خدمت انگلیسی':'عضو تیم') ?>. این نتیجه snapshot لحظه‌ای است؛ بقیه فیلدها نمایش داده نشده‌اند.</p><p><strong><?= $h($lookup['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($lookup['second']) ?></pre>
<?php if ($ready && !$readonly && $configured && content_lookup_matches_command() && content_command_kind_enabled($lookup['kind'])): ?><h4>پیشنهاد و مقایسهٔ متن جدید</h4><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="preview"><input type="hidden" name="compare" value="1"><input type="hidden" name="kind" value="<?= $h($lookup['kind']) ?>"><input type="hidden" name="object_id" value="<?= (int)$lookup['object_id'] ?>"><input type="hidden" name="token" value="<?= $h($lookup['token']) ?>"><label><?= $lookup['kind']==='service'?'عنوان فارسی':($lookup['kind']==='service_en'?'عنوان انگلیسی':'نام') ?> <input name="first" value="<?= $h($lookup['first']) ?>" <?= $lookup['kind']==='service_en'?'':'required' ?>></label><br><label><?= $lookup['kind']==='service'?'توضیح فارسی':($lookup['kind']==='service_en'?'توضیح انگلیسی':'نقش') ?><br><textarea name="second" rows="4" <?= $lookup['kind']==='service_en'?'':'required' ?>><?= $h($lookup['second']) ?></textarea></label><br><button class="btn">بررسی دوباره و مقایسه</button></form><?php else: ?><p>برای پیشنهاد تغییر، پیکربندی فرمان و دریافت باید فعال و هم‌منبع و هم‌مبدأ HTTPS باشند.</p><?php endif; ?><?php endif; ?>
<?php if ($ready && !$readonly && $configured): foreach (['service'=>'خدمت فارسی','service_en'=>'خدمت انگلیسی','team'=>'عضو تیم'] as $kind=>$label): if (!content_command_kind_enabled($kind)) continue; ?>
<h3>ویرایش <?= $h($label) ?> موجود</h3><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="preview"><input type="hidden" name="kind" value="<?= $h($kind) ?>"><label>شناسه سایت <input name="object_id" inputmode="numeric" required></label><br><label>نسخه کپی‌شده از پنل سایت <input name="token" minlength="64" maxlength="64" required dir="ltr"></label><br><label><?= $kind==='service'?'عنوان فارسی':($kind==='service_en'?'عنوان انگلیسی':'نام') ?> <input name="first" maxlength="<?= $kind==='team'?'100':'200' ?>" <?= $kind==='service_en'?'':'required' ?>></label><br><label><?= $kind==='service'?'توضیح فارسی':($kind==='service_en'?'توضیح انگلیسی':'نقش') ?><br><textarea name="second" rows="4" maxlength="<?= $kind==='team'?'200':'1000' ?>" <?= $kind==='service_en'?'':'required' ?>></textarea></label><br><button class="btn" type="submit">پیش‌نمایش متن جدید</button></form><?php endforeach; endif; ?>
<h3>۳۰ فرمان اخیر</h3><table class="data-table"><thead><tr><th>فرمان</th><th>نوع/شناسه سایت</th><th>مدیر</th><th>وضعیت</th><th>زمان ثبت</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= $h($r['command_id']) ?></td><td><?php $record=json_decode((string)$r['payload'],true); $mode=is_array($record)?content_command_mode($record):''; ?><?= $h($mode ?: $r['kind']) ?> / <?= (int)$r['object_id'] ?></td><td><?= (int)$r['actor_id'] ?></td><td><?= $h($r['state']) ?></td><td><?= $h($r['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5">فرمانی در این فهرست نیست؛ این اثبات وضعیت سایت نیست.</td></tr><?php endif; ?></tbody></table></div><?php include 'includes/footer.php'; ?>
